class Person {
  constructor(name) {
    this.name = name;
  }

  sayHello() {
    console.log("Hello World");
  }
}

class Student extends Person{
  constructor(name) {
    super(name);
  }
}

const stu = new Student("Alice");
stu.sayHello(); // Hello World
console.log(stu instanceof Student); // true
console.log(stu instanceof Person);  // true

class Person {
  constructor(name) {
    this.name = name;
  }

  sayHello() {
    console.log("Hello World");
  }
}

class Student extends Person{
  constructor(name) {
    super(name);
  }

  // 重写父类的方法
  sayHello() {
    console.log("Hi");
  }
}

const stu = new Student("Alice");
stu.sayHello(); // Hi

class Student extends Person{
  // ...
  sayHello() {
    super.sayHello();
    console.log("Hi");
  }
}

const stu = new Student("Alice");
stu.sayHello(); // Hello World
                // Hi

class Person {
  static print(...value) {
    console.log(...value);
  }
}

class Student extends Person {}

Student.print("Hello", "World");

function Person(name) {
  this.name = name;
}

Person.print = console.log;

// 继承自一个函数
class Student extends Person {}

Student.print("Hello", "World"); // Hello World
